package redact

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"flag"
	"fmt"
	"go/format"
	"io/fs"
	"os"
	"sort"
	"strings"
	"testing"
)

// The rule-set digest (§4.5) is a build-time constant in rules_digest.go,
// generated by `go generate ./redact` (which runs this test with
// -update-digest). The package itself computes no hash other than the
// pseudonyms (R12, AC28); this test recomputes the digest over the
// canonical rule table and fails when the constant has drifted.
var updateDigest = flag.Bool("update-digest", false, "rewrite rules_digest.go")

// canonicalRuleTable serialises everything that decides what matches:
// the version, every detector's ID, flags, patterns and validator names in
// §4.2 order, and the validator tables and limits the code reads.
func canonicalRuleTable() string {
	var b strings.Builder
	field := func(name, v string) { fmt.Fprintf(&b, "%s=%d:%s\n", name, len(v), v) }
	field("version", fmt.Sprint(RulesVersion))
	for _, d := range ruleTable() {
		field("detector", d.id)
		field("kind", fmt.Sprint(d.kind))
		field("extend", fmt.Sprint(d.extend))
		field("numeric", fmt.Sprint(d.numeric))
		field("classes", fmt.Sprint(d.classes))
		field("canon", d.canon)
	}
	countries := make([]string, 0, len(ibanLengths))
	for c := range ibanLengths {
		countries = append(countries, c)
	}
	sort.Strings(countries)
	for _, c := range countries {
		field("iban-length", fmt.Sprintf("%s%d", c, ibanLengths[c]))
	}
	field("iban-max", fmt.Sprint(ibanMax))
	field("unit-suffixes", strings.Join(unitSuffixes, ","))
	field("aws-prefixes", strings.Join(awsKeyPrefixes, ","))
	field("secret-key-words", strings.Join(secretKeyWords, ","))
	field("url-secret-params", strings.Join(urlSecretParams, ","))
	for _, v := range vendorPatterns {
		field("vendor", v.body+"|"+strings.Join(v.literals, ","))
	}
	for _, p := range keptPrefixes {
		field("ip-kept", p.String())
	}
	field("ip-bits", fmt.Sprint(ipv4Bits, sixToFourBits, ipv6Bits))
	field("id-window", fmt.Sprint(idWindow))
	field("arabic-marks", arabicMarks)
	field("digit-class", digitClass)
	field("body-line", fmt.Sprint(bodyLineMin, bodyLineMax, bodyLineShortMin))
	field("b64-decode-max", fmt.Sprint(b64DecodeMax))
	field("token-boundary", extendBoundaries)
	field("home-start", homeStartBefore)
	field("home-name-end", homeNameEnd)
	field("protected", pseudonymRe.String()+"|"+uuidRe.String()+"|"+hexRunRe.String())
	field("limits", fmt.Sprint(MaxEventInput, MaxLine, ItemDeadline))
	return b.String()
}

func digestOf(table string) string {
	sum := sha256.Sum256([]byte(table))
	return hex.EncodeToString(sum[:])
}

func TestRulesDigestIsCurrent(t *testing.T) {
	want := digestOf(canonicalRuleTable())
	if *updateDigest {
		if rulesDigestHex != want && rulesDigestVersion == RulesVersion {
			t.Fatalf("the rule table changed: raise RulesVersion (now %d) before regenerating the digest (R43)", RulesVersion)
		}
		src := fmt.Sprintf("// Code generated by go generate (TestRulesDigestIsCurrent); DO NOT EDIT.\n\n"+
			"package redact\n\n"+
			"// The rule-set digest of §4.5, fixed at build time.\n"+
			"const (\n\trulesDigestHex = %q\n\trulesDigestVersion = %d\n)\n", want, RulesVersion)
		out, err := format.Source([]byte(src))
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile("rules_digest.go", out, 0o600); err != nil {
			t.Fatal(err)
		}
		return
	}
	if rulesDigestHex != want || rulesDigestVersion != RulesVersion {
		t.Fatalf("rules_digest.go is stale (have %s for version %d, table gives %s for version %d): "+
			"raise RulesVersion if the rules changed, then run `go generate ./redact`",
			rulesDigestHex, rulesDigestVersion, want, RulesVersion)
	}
	got := RulesDigest()
	if hex.EncodeToString(got[:]) != want {
		t.Fatalf("RulesDigest() = %x, want %s", got, want)
	}
}

// R12, AC28: the only hash the package (non-test code) uses is HMAC-SHA-256
// in the pseudonym function.
func TestOnlyPseudonymsHash(t *testing.T) {
	pkg := os.DirFS(".")
	files, err := fs.Glob(pkg, "*.go")
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range files {
		if strings.HasSuffix(f, "_test.go") {
			continue
		}
		src, err := fs.ReadFile(pkg, f)
		if err != nil {
			t.Fatal(err)
		}
		for _, imp := range []string{`"crypto/sha256"`, `"crypto/hmac"`, `"crypto/sha1"`, `"crypto/md5"`, `"crypto/sha512"`, `"hash/`} {
			if bytes.Contains(src, []byte(imp)) && f != "pseudonym.go" {
				t.Errorf("%s imports %s; only pseudonym.go may hash (R12)", f, imp)
			}
		}
	}
}
